import React, { useEffect, useId, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Check, ChevronDown } from 'lucide-react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import {
  dropdownPanelMotion,
  liquidGlassPanelSpring,
  resetLiquidGlassPointer,
  trackLiquidGlassPointer,
} from './LiquidGlass';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface SelectOption {
  value: string;
  label: string;
}

export interface SelectProps {
  options: SelectOption[];
  value?: string;
  onChange: (value: string) => void;
  placeholder?: string;
  label?: string;
  className?: string;
  disabled?: boolean;
}

export const Select: React.FC<SelectProps> = ({
  options,
  value,
  onChange,
  placeholder = 'Select an option',
  label,
  className,
  disabled,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const [activeIndex, setActiveIndex] = useState(selectedIndex);
  const containerRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const selectId = useId();
  const listboxId = `${selectId}-listbox`;
  const selectedOption = options.find((option) => option.value === value);

  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('pointerdown', handlePointerDown);
    return () => document.removeEventListener('pointerdown', handlePointerDown);
  }, []);

  useEffect(() => {
    if (isOpen) setActiveIndex(selectedIndex);
  }, [isOpen, selectedIndex]);

  const choose = (index: number) => {
    const option = options[index];
    if (!option) return;
    onChange(option.value);
    setIsOpen(false);
    requestAnimationFrame(() => buttonRef.current?.focus());
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (disabled || options.length === 0) return;

    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      if (!isOpen) {
        setIsOpen(true);
        setActiveIndex(selectedIndex);
        return;
      }
      const direction = event.key === 'ArrowDown' ? 1 : -1;
      setActiveIndex((current) => (current + direction + options.length) % options.length);
      return;
    }

    if (event.key === 'Home' && isOpen) {
      event.preventDefault();
      setActiveIndex(0);
      return;
    }

    if (event.key === 'End' && isOpen) {
      event.preventDefault();
      setActiveIndex(options.length - 1);
      return;
    }

    if ((event.key === 'Enter' || event.key === ' ') && isOpen) {
      event.preventDefault();
      choose(activeIndex);
      return;
    }

    if (event.key === 'Escape' && isOpen) {
      event.preventDefault();
      setIsOpen(false);
    }
  };

  return (
    <div className={cn('relative mb-4 w-full', className)} ref={containerRef}>
      {label ? (
        <label htmlFor={selectId} className="mb-1.5 block text-sm font-medium text-gray-700 dark:text-gray-300">
          {label}
        </label>
      ) : null}

      <button
        ref={buttonRef}
        id={selectId}
        type="button"
        role="combobox"
        aria-controls={listboxId}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        aria-activedescendant={isOpen ? `${selectId}-option-${activeIndex}` : undefined}
        onClick={() => !disabled && options.length > 0 && setIsOpen((current) => !current)}
        onKeyDown={handleKeyDown}
        onPointerMove={trackLiquidGlassPointer}
        onPointerLeave={resetLiquidGlassPointer}
        disabled={disabled}
        className={cn(
          'wersee-liquid-glass wersee-liquid-glass--interactive flex min-h-12 w-full items-center justify-between rounded-[16px] px-4 py-2.5 text-sm text-white outline-none focus-visible:ring-2 focus-visible:ring-indigo-400/70',
          disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
          isOpen && 'ring-1 ring-white/20',
        )}
      >
        <span className={cn('truncate', !selectedOption && 'text-white/45')}>
          {selectedOption?.label ?? placeholder}
        </span>
        <motion.span animate={{ rotate: isOpen ? 180 : 0 }} transition={liquidGlassPanelSpring}>
          <ChevronDown className="h-4 w-4 text-white/50" aria-hidden="true" />
        </motion.span>
      </button>

      <AnimatePresence>
        {isOpen ? (
          <motion.div
            initial={{ ...dropdownPanelMotion.initial, y: -8 }}
            animate={dropdownPanelMotion.animate}
            exit={{ ...dropdownPanelMotion.exit, y: -5 }}
            transition={dropdownPanelMotion.transition}
            onPointerMove={trackLiquidGlassPointer}
            onPointerLeave={resetLiquidGlassPointer}
            className="wersee-liquid-glass wersee-liquid-glass--thick wersee-dropdown-panel absolute z-[250] mt-2 w-full origin-top overflow-hidden rounded-[18px] p-1.5"
          >
            <ul id={listboxId} role="listbox" aria-label={label ?? placeholder} className="max-h-64 overflow-auto">
              {options.map((option, index) => {
                const isSelected = value === option.value;
                const isActive = activeIndex === index;
                return (
                  <li
                    key={option.value}
                    id={`${selectId}-option-${index}`}
                    role="option"
                    aria-selected={isSelected}
                    className="list-none"
                  >
                    <button
                      type="button"
                      tabIndex={-1}
                      onPointerEnter={() => setActiveIndex(index)}
                      onClick={() => choose(index)}
                      className={cn(
                        'relative flex min-h-11 w-full items-center justify-between rounded-[13px] px-3.5 py-2.5 text-left text-sm text-white/70 outline-none transition-colors',
                        isActive && 'bg-white/[0.075] text-white',
                      )}
                    >
                      <span className="truncate">{option.label}</span>
                      {isSelected ? <Check className="h-4 w-4 shrink-0 text-indigo-300" aria-hidden="true" /> : null}
                    </button>
                  </li>
                );
              })}
            </ul>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
};
