import React, { forwardRef } from 'react';

export const liquidGlassSpring = {
  type: 'spring' as const,
  stiffness: 430,
  damping: 34,
  mass: 0.82,
};

export const liquidGlassPanelSpring = {
  type: 'spring' as const,
  stiffness: 280,
  damping: 30,
  mass: 0.86,
};

export const dropdownPanelMotion = {
  initial: { opacity: 0, y: 12, scale: 0.975 },
  animate: { opacity: 1, y: 0, scale: 1 },
  exit: { opacity: 0, y: 8, scale: 0.985 },
  transition: {
    type: 'tween' as const,
    duration: 0.26,
    ease: [0.22, 1, 0.36, 1] as [number, number, number, number],
  },
};

export const trackLiquidGlassPointer = (event: React.PointerEvent<HTMLElement>) => {
  if (event.pointerType === 'touch') return;
  const bounds = event.currentTarget.getBoundingClientRect();
  const x = ((event.clientX - bounds.left) / Math.max(bounds.width, 1)) * 100;
  const y = ((event.clientY - bounds.top) / Math.max(bounds.height, 1)) * 100;
  event.currentTarget.style.setProperty('--glass-x', `${Math.max(0, Math.min(100, x))}%`);
  event.currentTarget.style.setProperty('--glass-y', `${Math.max(0, Math.min(100, y))}%`);
};

export const resetLiquidGlassPointer = (event: React.PointerEvent<HTMLElement>) => {
  event.currentTarget.style.setProperty('--glass-x', '50%');
  event.currentTarget.style.setProperty('--glass-y', '0%');
};

type LiquidGlassSurfaceProps = React.HTMLAttributes<HTMLDivElement> & {
  tone?: 'regular' | 'thick' | 'clear';
  interactive?: boolean;
};

export const LiquidGlassSurface = forwardRef<HTMLDivElement, LiquidGlassSurfaceProps>(
  ({ tone = 'regular', interactive = false, className = '', onPointerMove, onPointerLeave, ...props }, ref) => (
    <div
      ref={ref}
      data-glass-tone={tone}
      className={`wersee-liquid-glass${interactive ? ' wersee-liquid-glass--interactive' : ''} ${className}`}
      onPointerMove={(event) => {
        if (interactive) trackLiquidGlassPointer(event);
        onPointerMove?.(event);
      }}
      onPointerLeave={(event) => {
        if (interactive) resetLiquidGlassPointer(event);
        onPointerLeave?.(event);
      }}
      {...props}
    />
  ),
);

LiquidGlassSurface.displayName = 'LiquidGlassSurface';
